def kennungen_vergeben(apps, schema_editor):
    Objekt = apps.get_model("kundenportal", "Objekt")
    for o in Objekt.objects.filter(kennung__isnull=True):
        o.kennung = uuid.uuid4()
        o.save(update_fields=["kennung"])


def _hash(w) -> str:
    # muss Statuswechsel.berechne_hash entsprechen
    daten = {"lauf": w.lauf_id, "report": w.report_id, "status": w.status, "benutzer": w.benutzer_id,
             "zeit": w.zeit.isoformat(), "notiz": w.notiz, "bezug": w.bezug_hash, "vorher": w.vorher_hash}
    return hashlib.sha256(json.dumps(daten, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def verlauf_verketten(apps, schema_editor):
    """Bestehende Statuswechsel (nur Test- und Entwicklungsdaten, nichts ist veröffentlicht) erhalten ihre Kette.
    Der Inhaltsbezug bleibt bei Altständen leer und wird als Altbestand angezeigt; nichts wird umetikettiert."""
    Statuswechsel = apps.get_model("kundenportal", "Statuswechsel")
    letzte = {}
    for w in Statuswechsel.objects.order_by("zeit", "id"):
        schluessel = (w.lauf_id, w.report_id)
        w.vorher_hash = letzte.get(schluessel, "")
        w.eintrag_hash = _hash(w)
        w.save(update_fields=["vorher_hash", "eintrag_hash"])
        letzte[schluessel] = w.eintrag_hash


